import { Component } from "react";
import { Search, Filter, X, LayoutGrid, List, ChevronLeft, ChevronRight } from "lucide-react";
import { maladumSets } from "../resource/dataSet/setMeta";
import { allCards, allTypes, filterCards } from "../util/cardCatalog";
import CardIcon from "./CardIcon";
import CardView from "./CardView";

const PAGE_SIZE = { grid: 24, list: 30 };

// 1..N 페이지 배열을 ..로 축약 (현재 ±2, 양쪽 끝 1씩)
function pageWindow(total, current) {
    if (total <= 7) return Array.from({ length: total }, (_, i) => i + 1);
    const out = new Set([1, total, current - 1, current, current + 1]);
    const arr = [...out].filter(n => n >= 1 && n <= total).sort((a, b) => a - b);
    const withGaps = [];
    for (let i = 0; i < arr.length; i++) {
        withGaps.push(arr[i]);
        if (i < arr.length - 1 && arr[i + 1] !== arr[i] + 1) withGaps.push("…");
    }
    return withGaps;
}

class CardBrowser extends Component {

    state = {
        setId: "base-game",
        type: "",
        query: "",
        selectedCard: null,
        viewMode: "grid",
        page: 1,
    }

    handler = {
        selectSet: (id) => this.setState({ setId: id, type: "", page: 1, selectedCard: null }),
        selectType: (t) => this.setState({ type: t, page: 1 }),
        changeQuery: (e) => this.setState({ query: e.target.value, page: 1 }),
        clearQuery: () => this.setState({ query: "", page: 1 }),
        openCard: (c) => this.setState({ selectedCard: c }),
        closeCard: () => this.setState({ selectedCard: null }),
        setViewMode: (m) => this.setState({ viewMode: m, page: 1 }),
        goPage: (p) => this.setState({ page: p }),
    }

    renderGridItem(c, isActive) {
        return (
            <button
                key={`${c.setId}-${c.globalId}`}
                onClick={() => this.handler.openCard(c)}
                className={`group text-left rounded-xl border p-3 transition-all ${
                    isActive
                        ? "border-rose-400/70 bg-rose-500/10 shadow-lg shadow-rose-500/10"
                        : "border-white/10 bg-white/[0.02] hover:border-rose-400/40 hover:bg-white/[0.04]"
                }`}
            >
                <div className="flex items-center justify-between gap-2 mb-2">
                    <span className="text-[10px] font-mono tracking-widest text-slate-500">
                        #{String(c.globalId || c.id).padStart(3, "0")}
                    </span>
                    <div className="flex items-center gap-1">
                        {(c.footer?.left || []).slice(0, 2).map((t, i) => (
                            <CardIcon key={i} name={t.name} size={14} />
                        ))}
                    </div>
                </div>
                <div className="text-sm font-semibold text-white leading-tight break-keep">
                    {c.card_ko}
                </div>
                <div className="mt-1 text-[11px] text-slate-500 truncate">
                    {c.type_ko}
                </div>
            </button>
        );
    }

    renderListItem(c, isActive) {
        return (
            <button
                key={`${c.setId}-${c.globalId}`}
                onClick={() => this.handler.openCard(c)}
                className={`group grid grid-cols-[48px_28px_1fr_120px_1fr] items-center gap-3 rounded-lg border px-3 py-2 text-left transition-all ${
                    isActive
                        ? "border-rose-400/70 bg-rose-500/10"
                        : "border-white/5 bg-white/[0.02] hover:border-rose-400/40 hover:bg-white/[0.04]"
                }`}
            >
                <span className="text-[11px] font-mono tracking-widest text-slate-500">
                    #{String(c.globalId || c.id).padStart(3, "0")}
                </span>
                <span className="flex items-center justify-center">
                    {c.footer?.left?.[0]?.name
                        ? <CardIcon name={c.footer.left[0].name} size={18} />
                        : null}
                </span>
                <span className="text-sm font-semibold text-white truncate">
                    {c.card_ko}
                </span>
                <span className="text-xs text-rose-200/80 truncate">
                    {c.type_ko}
                </span>
                <span className="text-xs text-slate-500 truncate">
                    {c.card}
                </span>
            </button>
        );
    }

    renderPagination(totalPages) {
        if (totalPages <= 1) return null;
        const { page } = this.state;
        const window = pageWindow(totalPages, page);
        const btn = "min-w-[32px] h-8 px-2 rounded-lg text-xs ring-1 transition-colors";
        return (
            <div className="flex items-center justify-center gap-1 mt-5">
                <button
                    disabled={page === 1}
                    onClick={() => this.handler.goPage(page - 1)}
                    className={`${btn} inline-flex items-center justify-center ${
                        page === 1
                            ? "bg-white/[0.02] text-slate-600 ring-white/5 cursor-not-allowed"
                            : "bg-white/[0.03] text-slate-300 ring-white/10 hover:bg-white/[0.08]"
                    }`}
                >
                    <ChevronLeft className="w-3.5 h-3.5" />
                </button>
                {window.map((p, i) => p === "…" ? (
                    <span key={`e${i}`} className="px-1 text-xs text-slate-600 select-none">…</span>
                ) : (
                    <button
                        key={p}
                        onClick={() => this.handler.goPage(p)}
                        className={`${btn} ${
                            p === page
                                ? "bg-gradient-to-r from-rose-500 to-fuchsia-500 text-white ring-rose-400/50 font-semibold"
                                : "bg-white/[0.03] text-slate-300 ring-white/10 hover:bg-white/[0.08]"
                        }`}
                    >
                        {p}
                    </button>
                ))}
                <button
                    disabled={page === totalPages}
                    onClick={() => this.handler.goPage(page + 1)}
                    className={`${btn} inline-flex items-center justify-center ${
                        page === totalPages
                            ? "bg-white/[0.02] text-slate-600 ring-white/5 cursor-not-allowed"
                            : "bg-white/[0.03] text-slate-300 ring-white/10 hover:bg-white/[0.08]"
                    }`}
                >
                    <ChevronRight className="w-3.5 h-3.5" />
                </button>
            </div>
        );
    }

    render() {
        const { setId, type, query, selectedCard, viewMode, page } = this.state;

        const cards = allCards();
        const filtered = filterCards(cards, { setId, type, query });
        const types = allTypes(cards.filter(c => c.setId === setId));
        const activeSet = maladumSets.find(s => s.id === setId);

        const pageSize = PAGE_SIZE[viewMode];
        const totalPages = Math.max(1, Math.ceil(filtered.length / pageSize));
        const currentPage = Math.min(page, totalPages);
        const startIdx = (currentPage - 1) * pageSize;
        const paged = filtered.slice(startIdx, startIdx + pageSize);
        const rangeStart = filtered.length === 0 ? 0 : startIdx + 1;
        const rangeEnd = Math.min(startIdx + pageSize, filtered.length);

        return (
            <div className="grid grid-cols-12 gap-5 min-h-[80vh]">
                {/* 좌측: 세트 & 필터 */}
                <aside className="col-span-3 flex flex-col gap-4">
                    <div className="rounded-2xl border border-white/10 bg-white/[0.03] p-4">
                        <div className="mb-3 flex items-center gap-2 text-xs font-semibold tracking-widest uppercase text-rose-300/80">
                            <Filter className="w-3.5 h-3.5" /> 컨텐츠 세트
                        </div>
                        <div className="flex flex-col gap-1.5">
                            {maladumSets.map(s => (
                                <button
                                    key={s.id}
                                    onClick={() => this.handler.selectSet(s.id)}
                                    className={`group flex items-center justify-between gap-2 rounded-lg px-3 py-2 text-left transition-colors ${
                                        s.id === setId
                                            ? "bg-gradient-to-r " + s.accent + " text-white shadow-md"
                                            : "bg-white/[0.02] text-slate-300 hover:bg-white/[0.06]"
                                    }`}
                                >
                                    <div className="min-w-0">
                                        <div className="text-sm font-semibold truncate">{s.name_ko}</div>
                                        <div className="text-[10px] opacity-70 truncate">{s.name}</div>
                                    </div>
                                    <span className={`text-xs tabular-nums ${s.id === setId ? "text-white" : "text-slate-500"}`}>
                                        {s.data.cards.length}
                                    </span>
                                </button>
                            ))}
                        </div>
                    </div>

                    <div className="rounded-2xl border border-white/10 bg-white/[0.03] p-4">
                        <div className="mb-3 flex items-center gap-2 text-xs font-semibold tracking-widest uppercase text-rose-300/80">
                            카드 유형
                        </div>
                        <div className="flex flex-wrap gap-1.5">
                            <button
                                onClick={() => this.handler.selectType("")}
                                className={`rounded-full px-2.5 py-1 text-xs ${
                                    type === ""
                                        ? "bg-rose-500/25 text-rose-100 ring-1 ring-rose-300/50"
                                        : "bg-white/[0.03] text-slate-400 ring-1 ring-white/10 hover:bg-white/[0.08]"
                                }`}
                            >
                                전체
                            </button>
                            {types.map(t => (
                                <button
                                    key={t}
                                    onClick={() => this.handler.selectType(t)}
                                    className={`rounded-full px-2.5 py-1 text-xs ${
                                        type === t
                                            ? "bg-rose-500/25 text-rose-100 ring-1 ring-rose-300/50"
                                            : "bg-white/[0.03] text-slate-400 ring-1 ring-white/10 hover:bg-white/[0.08]"
                                    }`}
                                >
                                    {t}
                                </button>
                            ))}
                        </div>
                    </div>
                </aside>

                {/* 중앙: 카드 리스트 */}
                <section className="col-span-5">
                    <div className="mb-4 flex items-center justify-between gap-3">
                        <div>
                            <div className="text-xs font-semibold tracking-widest uppercase text-rose-300/80">
                                {activeSet?.name_ko_full}
                            </div>
                            <div className="mt-0.5 text-sm text-slate-300">
                                <span className="text-slate-500">{rangeStart}-{rangeEnd} / </span>
                                <span className="text-white font-semibold">{filtered.length}</span>
                                <span className="text-slate-500"> (전체 {activeSet?.data.cards.length}장)</span>
                            </div>
                        </div>
                        <div className="flex items-center gap-2">
                            <div className="inline-flex rounded-lg bg-white/[0.04] p-0.5 ring-1 ring-white/10">
                                <button
                                    onClick={() => this.handler.setViewMode("grid")}
                                    title="카드 뷰"
                                    className={`inline-flex items-center justify-center gap-1 rounded-md px-2 py-1 text-xs ${
                                        viewMode === "grid"
                                            ? "bg-rose-500/25 text-rose-100 ring-1 ring-rose-300/40"
                                            : "text-slate-400 hover:text-slate-200"
                                    }`}
                                >
                                    <LayoutGrid className="w-3.5 h-3.5" />
                                </button>
                                <button
                                    onClick={() => this.handler.setViewMode("list")}
                                    title="목록 뷰"
                                    className={`inline-flex items-center justify-center gap-1 rounded-md px-2 py-1 text-xs ${
                                        viewMode === "list"
                                            ? "bg-rose-500/25 text-rose-100 ring-1 ring-rose-300/40"
                                            : "text-slate-400 hover:text-slate-200"
                                    }`}
                                >
                                    <List className="w-3.5 h-3.5" />
                                </button>
                            </div>
                            <div className="relative w-56">
                                <Search className="absolute left-3 top-2.5 w-4 h-4 text-slate-500 pointer-events-none" />
                                <input
                                    type="text"
                                    value={query}
                                    onChange={this.handler.changeQuery}
                                    placeholder="카드 검색..."
                                    className="w-full rounded-lg bg-white/[0.04] px-9 py-2 text-sm text-white placeholder:text-slate-500 ring-1 ring-white/10 outline-none focus:ring-rose-400/40"
                                />
                                {query && (
                                    <button
                                        onClick={this.handler.clearQuery}
                                        className="absolute right-2 top-2 rounded p-1 text-slate-400 hover:bg-white/5"
                                    >
                                        <X className="w-3.5 h-3.5" />
                                    </button>
                                )}
                            </div>
                        </div>
                    </div>

                    {filtered.length === 0 ? (
                        <div className="py-16 text-center text-sm text-slate-500">
                            조건에 맞는 카드가 없습니다.
                        </div>
                    ) : viewMode === "grid" ? (
                        <div className="grid grid-cols-2 gap-3 lg:grid-cols-3">
                            {paged.map(c => this.renderGridItem(
                                c,
                                selectedCard?.globalId === c.globalId && selectedCard?.setId === c.setId
                            ))}
                        </div>
                    ) : (
                        <div className="flex flex-col gap-1.5">
                            <div className="grid grid-cols-[48px_28px_1fr_120px_1fr] items-center gap-3 px-3 py-1.5 text-[10px] font-semibold tracking-widest uppercase text-slate-500">
                                <span>No.</span>
                                <span />
                                <span>카드명</span>
                                <span>유형</span>
                                <span>원제</span>
                            </div>
                            {paged.map(c => this.renderListItem(
                                c,
                                selectedCard?.globalId === c.globalId && selectedCard?.setId === c.setId
                            ))}
                        </div>
                    )}

                    {this.renderPagination(totalPages)}
                </section>

                {/* 우측: 카드 상세 */}
                <aside className="col-span-4">
                    <div className="sticky top-4 h-[82vh]">
                        {selectedCard ? (
                            <CardView card={selectedCard} onClose={this.handler.closeCard} />
                        ) : (
                            <div className="flex h-full flex-col items-center justify-center rounded-2xl border border-dashed border-white/10 bg-white/[0.02] text-center p-8">
                                <div className="mb-3 text-3xl">🃏</div>
                                <p className="text-sm text-slate-400">왼쪽에서 카드를 선택하세요</p>
                                <p className="mt-2 text-xs text-slate-600">각 카드의 공포 단계별 효과를 확인할 수 있습니다</p>
                            </div>
                        )}
                    </div>
                </aside>
            </div>
        );
    }
}

export default CardBrowser;
